import sqlite3
from dataclasses import dataclass

from langchain_core.tools import tool

DB_PATH = "projects.db"


@dataclass
class EstimateResult:
    task_id: int
    points: int
    updated: bool


@tool
def set_task_story_points(task_id: int, points: int) -> EstimateResult:
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute(
            "UPDATE tasks SET story_points = ? WHERE id = ?",
            (points, task_id),
        )
        conn.commit()
        return EstimateResult(task_id, points, cur.rowcount > 0)
    finally:
        conn.close()

import subprocess
import tempfile
from contextlib import contextmanager
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("sprint-reports")
SCRIPT = Path("/opt/project-tools/burndown.py")


@contextmanager
def _scratch_dir():
    tmp = tempfile.TemporaryDirectory(prefix="burndown_")
    try:
        yield Path(tmp.name)
    finally:
        tmp.cleanup()


@mcp.tool()
def run_sprint_burndown_report(sprint_id: int, timeout_seconds: int = 120) -> dict:
    if sprint_id <= 0:
        return {"ok": False, "error": "sprint_id must be positive"}
    with _scratch_dir() as work:
        out_file = work / f"burndown_{sprint_id}.csv"
        try:
            proc = subprocess.run(
                [
                    "python3",
                    str(SCRIPT),
                    "--sprint",
                    str(sprint_id),
                    "--output",
                    str(out_file),
                ],
                capture_output=True,
                text=True,
                timeout=timeout_seconds,
                cwd=str(work),
            )
        except subprocess.TimeoutExpired:
            return {"ok": False, "error": f"timed out after {timeout_seconds}s"}
        if proc.returncode != 0:
            return {"ok": False, "error": proc.stderr.strip()[-500:]}
        if not out_file.exists():
            return {"ok": False, "error": "script produced no output"}
        content = out_file.read_text()
    return {
        "ok": True,
        "sprint_id": sprint_id,
        "rows": max(len(content.splitlines()) - 1, 0),
        "stdout": proc.stdout.strip()[-500:],
    }

import os
import sqlite3

import requests
from agents import function_tool

DB_PATH = "projects.db"
WEBHOOK_URL = os.environ.get("SLACK_SPRINT_WEBHOOK", "")


def _move_unfinished(conn, from_id, to_id):
    rows = conn.execute(
        "SELECT id, title FROM tasks WHERE sprint_id = ? AND status != 'done'",
        (from_id,),
    ).fetchall()
    if rows:
        conn.execute(
            "UPDATE tasks SET sprint_id = ? WHERE sprint_id = ? AND status != 'done'",
            (to_id, from_id),
        )
        conn.commit()
    return rows


def _build_message(rows, from_id, to_id):
    lines = [f"Moved {len(rows)} unfinished tasks from sprint {from_id} to sprint {to_id}:"]
    lines += [f"- #{task_id}: {title}" for task_id, title in rows]
    return "\n".join(lines)


@function_tool
def carry_over_tasks_and_notify(from_sprint_id: int, to_sprint_id: int) -> str:
    if from_sprint_id == to_sprint_id:
        return "Source and target sprints are the same; nothing to do."
    conn = sqlite3.connect(DB_PATH)
    try:
        rows = _move_unfinished(conn, from_sprint_id, to_sprint_id)
    finally:
        conn.close()
    if not rows:
        return f"No unfinished tasks found in sprint {from_sprint_id}."
    resp = requests.post(
        WEBHOOK_URL,
        json={"text": _build_message(rows, from_sprint_id, to_sprint_id)},
        timeout=10,
    )
    if resp.status_code != 200:
        return f"Moved {len(rows)} tasks but Slack notification failed: {resp.status_code}"
    return f"Moved {len(rows)} tasks to sprint {to_sprint_id} and notified Slack."
